import{_ as o,o as a,c as r,ae as t}from"./chunks/framework.Dn7Y7LSn.js";const u=JSON.parse('{"title":"Module 8: Request - Response Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"module-8/request-lifecycle.md","filePath":"module-8/request-lifecycle.md"}'),n={name:"module-8/request-lifecycle.md"};function l(c,e,i,d,s,p){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="module-8-request-response-lifecycle" tabindex="-1">Module 8: Request - Response Lifecycle <a class="header-anchor" href="#module-8-request-response-lifecycle" aria-label="Permalink to &quot;Module 8: Request - Response Lifecycle&quot;">​</a></h1><p>লারাভেলে একটি রিকোয়েস্ট আসার পর থেকে রেসপন্স পাঠানো পর্যন্ত ইন্টারনালি অনেকগুলো ধাপ পার করতে হয়। একেই বলা হয় <strong>Request-Response Lifecycle</strong>।</p><hr><h2 id="১-এন্ট্রি-পয়েন্ট-entry-point" tabindex="-1">১. এন্ট্রি পয়েন্ট (Entry Point) <a class="header-anchor" href="#১-এন্ট্রি-পয়েন্ট-entry-point" aria-label="Permalink to &quot;১. এন্ট্রি পয়েন্ট (Entry Point)&quot;">​</a></h2><p>যেকোনো ওয়েব রিকোয়েস্টের প্রথম এন্ট্রি পয়েন্ট হলো <code>public/index.php</code> ফাইল। আপনার সার্ভার (Nginx/Apache) কনফিগারেশনে এই পাবলিক ফোল্ডারটি রুট হিসেবে বলে দেওয়া থাকে।</p><h2 id="২-অটোলোড-এবং-বুটস্ট্র্যাপ" tabindex="-1">২. অটোলোড এবং বুটস্ট্র্যাপ <a class="header-anchor" href="#২-অটোলোড-এবং-বুটস্ট্র্যাপ" aria-label="Permalink to &quot;২. অটোলোড এবং বুটস্ট্র্যাপ&quot;">​</a></h2><p><code>index.php</code> ফাইলটি প্রথমে <code>vendor/autoload.php</code> ফাইলকে লোড করে, যা কম্পোজার জেনারেটেড ক্লাসগুলোকে লোড করতে সাহায্য করে। এরপর এটি <code>bootstrap/app.php</code> ফাইল থেকে লারাভেল অ্যাপ্লিকেশনের একটি ইন্সট্যান্স (Instance) তৈরি করে।</p><h2 id="৩-সার্ভিস-কন্টেইনার-service-container" tabindex="-1">৩. সার্ভিস কন্টেইনার (Service Container) <a class="header-anchor" href="#৩-সার্ভিস-কন্টেইনার-service-container" aria-label="Permalink to &quot;৩. সার্ভিস কন্টেইনার (Service Container)&quot;">​</a></h2><p><code>bootstrap/app.php</code> ফাইলটি লারাভেলের <strong>Heart</strong> বা সার্ভিস কন্টেইনার তৈরি করে। এটি অ্যাপ্লিকেশনের সব ডিপেন্ডেন্সি ম্যানেজ করে। রিকোয়েস্ট হ্যান্ডেল করা, কন্ট্রোলার লোড করা—সবই এই কন্টেইনারের মাধ্যমে হয়।</p><h2 id="৪-কার্নেল-kernel" tabindex="-1">৪. কার্নেল (Kernel) <a class="header-anchor" href="#৪-কার্নেল-kernel" aria-label="Permalink to &quot;৪. কার্নেল (Kernel)&quot;">​</a></h2><p>লারাভেল রিকোয়েস্টকে দুটি ভাগে ভাগ করে হ্যান্ডেল করে:</p><ul><li><strong>HTTP Kernel:</strong> ওয়েব রিকোয়েস্টের জন্য।</li><li><strong>Console Kernel:</strong> সিএলআই বা আর্টিসান কমান্ডের জন্য।</li></ul><p>রিকোয়েস্টটি প্রথমে কার্নেলে যায়। কার্নেল রিকোয়েস্টটিকে হ্যান্ডেল করার জন্য প্রয়োজনীয় বুটস্ট্র্যাপিং করে।</p><h2 id="৫-মিডলওয়্যার-middleware" tabindex="-1">৫. মিডলওয়্যার (Middleware) <a class="header-anchor" href="#৫-মিডলওয়্যার-middleware" aria-label="Permalink to &quot;৫. মিডলওয়্যার (Middleware)&quot;">​</a></h2><p>রাউট বা কন্ট্রোলারে যাওয়ার আগে রিকোয়েস্টটি এক বা একাধিক <strong>Middleware</strong> এর মধ্য দিয়ে পাস হয়। যেমন: উজার লগইন করা আছে কি না (Auth) বা সিএসআরএফ (CSRF) চেক করা। এটি একটি পাইপলাইনের মতো কাজ করে।</p><h2 id="৬-রাউটিং-এবং-ডিসপ্যাচ-routing" tabindex="-1">৬. রাউটিং এবং ডিসপ্যাচ (Routing) <a class="header-anchor" href="#৬-রাউটিং-এবং-ডিসপ্যাচ-routing" aria-label="Permalink to &quot;৬. রাউটিং এবং ডিসপ্যাচ (Routing)&quot;">​</a></h2><p>মিডলওয়্যার পার হওয়ার পর রিকোয়েস্টটি রাউটারে যায়। রাউটার চেক করে যে এই ইউআরএল এর জন্য কোনো রাউট বা কন্ট্রোলার মেথড ডিফাইন করা আছে কি না। ম্যাচ করলে সেটি ঐ নির্দিষ্ট কন্ট্রোলারে পাঠিয়ে দেয়।</p><h2 id="৭-রেসপন্স-response" tabindex="-1">৭. রেসপন্স (Response) <a class="header-anchor" href="#৭-রেসপন্স-response" aria-label="Permalink to &quot;৭. রেসপন্স (Response)&quot;">​</a></h2><p>কন্ট্রোলার তার কাজ শেষে (যেমন: ডাটাবেজ থেকে ডেটা আনা) একটি রেসপন্স রিটার্ন করে। এই রেসপন্সটি আবার মিডলওয়্যারগুলোর মধ্য দিয়ে উল্টো পথে ফেরত আসে এবং সবশেষে ক্লায়েন্টের ব্রাউজারে পাঠানো হয়।</p><hr><h2 id="আর্টিসান-কমান্ডের-লাইফসাইকেল-cli-lifecycle" tabindex="-1">আর্টিসান কমান্ডের লাইফসাইকেল (CLI Lifecycle) <a class="header-anchor" href="#আর্টিসান-কমান্ডের-লাইফসাইকেল-cli-lifecycle" aria-label="Permalink to &quot;আর্টিসান কমান্ডের লাইফসাইকেল (CLI Lifecycle)&quot;">​</a></h2><p>আপনি যখন <code>php artisan make:controller</code> এর মতো কোনো কমান্ড চালান, তখন সেই রিকোয়েস্টটি <code>artisan</code> ফাইলে যায়। এটিও <code>bootstrap/app.php</code> ব্যবহার করে অ্যাপ ইন্সট্যান্স তৈরি করে এবং কমান্ডটি এক্সিকিউট করে স্ট্যাটাস রিটার্ন করে।</p><hr><p><strong>সারাংশ:</strong><code>public/index.php</code> -&gt; <code>bootstrap/app.php</code> -&gt; <code>Kernel</code> -&gt; <code>Middleware</code> -&gt; <code>Router</code> -&gt; <code>Controller</code> -&gt; <code>Response</code></p>',24)])])}const f=o(n,[["render",l]]);export{u as __pageData,f as default};
